from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

class Order(BaseModel):
    order_id: str
    amount_cents: int
    currency: str = "USD"

class Accepted(BaseModel):
    order_id: str

@app.post("/orders", response_model=Accepted)
async def create_order(order: Order):
    return Accepted(order_id=order.order_id)

type OrderEvent =
  | { kind: "created"; id: string; total: number }
  | { kind: "cancelled"; id: string; reason: string };

function describe(e: OrderEvent): string {
  switch (e.kind) {
    case "created":
      return `order ${e.id} for ${e.total}`;
    case "cancelled":
      return `order ${e.id} cancelled: ${e.reason}`;
    default: {
      const unreachable: never = e;
      return unreachable;
    }
  }
}

import { z } from "zod";

const Customer = z.object({
  id: z.string(),
  email: z.string().nullable(),
  seats: z.number().int().nonnegative(),
});
type Customer = z.infer<typeof Customer>;

export async function getCustomer(base: string, id: string): Promise<Customer> {
  const res = await fetch(`${base}/customers/${id}`);
  if (!res.ok) throw new Error(`upstream ${res.status}`);
  return Customer.parse(await res.json());
}

