from datetime import timedelta
from temporalio import workflow
from temporalio.common import RetryPolicy

@workflow.defn
class TriageWorkflow:
    @workflow.run
    async def run(self, ticket_id: str) -> str:
        opts = dict(
            start_to_close_timeout=timedelta(minutes=2),
            retry_policy=RetryPolicy(maximum_attempts=4),
        )
        messages = [ticket_id]
        for step in range(8):
            reply = await workflow.execute_activity("call_model", messages, **opts)
            if not reply.get("tool"):
                return reply["text"]
            key = f"{workflow.info().workflow_id}-{step}"
            messages.append(await workflow.execute_activity("run_tool", [reply, key], **opts))
        return "escalated"

import json, statistics

def grade(case, trace):
    calls = [s["tool"] for s in trace["steps"] if s.get("tool")]
    return {
        "outcome": trace["final_state"] == case["expected_state"],
        "no_forbidden": not set(calls) & set(case["forbidden_tools"]),
        "within_budget": len(trace["steps"]) <= case["max_steps"],
    }

def run_suite(cases, run_agent, trials=3):
    report = {}
    for case in cases:
        passes = [all(grade(case, run_agent(case["input"])).values())
                  for _ in range(trials)]
        report[case["id"]] = statistics.mean(passes)
    return report

print(json.dumps(run_suite([], lambda x: {}), indent=2))

